import{_ as i,c as r,a as o,I as d,b as t,u as a,C as s,t as l,d as h,w as u,r as c,o as p}from"./index-BBylxyrb.js";const w={class:"page"},y={class:"band narrow doc"},f={class:"prose"},m=["href"],v={class:"back-line"},b={__name:"PrivacyView",setup(g){return(k,e)=>{const n=c("RouterLink");return p(),r("main",w,[o("section",y,[e[5]||(e[5]=o("p",{class:"eyebrow"},"Privacy",-1)),e[6]||(e[6]=o("h1",null,"Privacy notice",-1)),o("div",f,[e[2]||(e[2]=d("<p data-v-30a207d9> This is the privacy notice for the Confab website. It is written plainly because there is not much to it. The Confab app itself keeps your conversations on your Mac; this notice is about the small amount of information the website collects. </p><h2 data-v-30a207d9>What we collect</h2><p data-v-30a207d9> What you type into a form. If you request early access, we collect your name and email. If you use the contact form, we collect your name, email, and the message you write. </p><p data-v-30a207d9> We also measure how this site is used, so we can see which pages help and which ones confuse. That covers the pages you visit, the links and buttons you click, and a replay of your visit as a sequence of page interactions. Anything you type is masked before it leaves your browser, so what you enter into a form never appears in a replay. </p><p data-v-30a207d9> This is done without cookies. Nothing is stored on your device, and nothing follows you to other sites. Each visit is measured on its own, so we cannot connect this visit to an earlier one, and we do not build a profile of you. There are no advertising pixels and we sell nothing to anyone. </p><h2 data-v-30a207d9>Where it goes</h2><p data-v-30a207d9> When you submit a form, the details are stored in a database and emailed to us so we can reply. We use Cloudflare to run the site and the form handler, Resend to send the email, and PostHog for the usage measurement described above, which is processed on servers in the United States. All three act as processors on our behalf and only handle the information needed to do that job. Your details are not sold or shared with anyone else. </p><h2 data-v-30a207d9>Why we keep it</h2><p data-v-30a207d9> So we can reply to you, and so we can tell you when Confab is ready to download or when there is news you asked to hear about. That is the only use. </p><h2 data-v-30a207d9>How long we keep it, and how to be deleted</h2>",10)),o("p",null,[e[0]||(e[0]=t(" We keep your details only as long as we need them for those purposes. You can ask us to delete everything we hold about you at any time, and we will. Email ")),o("a",{href:`mailto:${a(s)}`},l(a(s)),9,m),e[1]||(e[1]=t(" and we will remove your data and confirm when it is done. "))]),e[3]||(e[3]=o("p",{class:"note"}," If we ever change how any of this works, we will update this page first. ",-1))]),o("p",v,[h(n,{class:"back-link",to:"/"},{default:u(()=>e[4]||(e[4]=[t("Back to the overview")])),_:1})])])])}}},C=i(b,[["__scopeId","data-v-30a207d9"]]);export{C as default};
